}

/* Tabelas de Dados (Informações Essenciais, Hierarquia) */
table.data-list {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}
table.data-list tr {
    page-break-inside: avoid;
}

table.data-list th,
table.data-list td {
    padding: 10px;
    text-align: left;
    vertical-align: top;
    border-bottom: 1px solid #ddd;
}

table.data-list th {
    background-color: #f8f9fa;
