    padding: 10px 0; /* Apenas espaçamento vertical */
}

/* Listas (Habilidades, Cursos, Características) */
.habilidade-list,
.curso-list,
.caracteristica-list,
.risco-list { 
    list-style: none;
    padding-left: 0;
    margin-top: 10px;
}

/* Estilo padrão (compacto) para o PDF */
.habilidade-list li,
.curso-list li,
.caracteristica-list li,
.risco-list li { 
    padding: 2px 0; /* <-- Padding compacto para PDF */
    line-height: 1.2; /* <-- Entrelinha compacta para PDF */
    border-bottom: 1px dotted #ccc;
    page-break-inside: avoid;
    overflow: hidden; /* Clearfix para o float do ícone */
}

/* Override (espaçamento maior) para o Navegador */
body.html-render .habilidade-list li,
body.html-render .curso-list li,
body.html-render .caracteristica-list li,
body.html-render .risco-list li {
    padding: 8px 0; /* <-- Padding maior para HTML */
    line-height: 1.4; /* <-- Entrelinha normal para HTML */
    border-bottom: 1px dotted #eee;
}


.habilidade-nome {
    font-size: 10.5pt;
    color: #222;
}

.habilidade-descricao {
    font-size: 9pt;
    color: #555;
    padding-left: 20px; 
}

.skill-type-header {
    font-size: 11pt;
    font-weight: bold;
    color: #444;
    margin-top: 10px;
}

.skill-type-header i {
    margin-right: 5px;
}

/* Ícones de lista (Alinhamento) */
.curso-list li i,
.caracteristica-list li i,
.habilidade-list li i,
.risco-list li i { 
    color: #198754;
    margin-right: 8px;
    margin-top: 3px; 
    width: 1.2em; 
    text-align: center; 
    float: left; 
}

/* Ícones de Risco pretos */
.risco-list li i {
    color: #000 !important; 
}


.item-content {
    display: block;
    overflow: hidden; 
}

.caracteristica-list li {
    /* font-weight: normal; */
}

/* Padrão (para PDF): 1 Coluna */
.skill-container,
.section-container {
    width: 100%;
    overflow: hidden;
}
.skill-column,
.section-column {
    width: 100%;
    float: none;
    margin-right: 0;
}

/* Apenas no Navegador (HTML): Ativa 2 Colunas */
body.html-render .skill-container,
body.html-render .section-container {
    overflow: hidden; /* Clearfix para floats */
}
body.html-render .skill-column,
body.html-render .section-column {
    width: 49%;
    float: left;
}
body.html-render .skill-column:first-child,
body.html-render .section-column:first-child {
    margin-right: 2%;
}


/* --- ESTILOS DE IMPRESSÃO (E PDF) --- */
@media print {
    body {
        font-size: 9pt;
        background-color: #fff;
        color: #000;
    }

    .no-print {
        display: none !important;
    }

    /* Reseta o container para o modo de impressão */
    .container {
        width: 100%;
        margin: 0;
        padding: 0;
        box-shadow: none;
        border: none;
        border-radius: 0;
        background-color: #fff;
    }

    /* Força a impressão de cores/ícones do FontAwesome */
    table.data-list th i,
    .curso-list li i,
    .caracteristica-list li i,
    .habilidade-list li i,
    .risco-list li i, 
    .h2-custom i,
    .h5-custom i {
        color: #000 !important;
        -webkit-print-color-adjust: exact;
        color-adjust: exact;
    }

    .h2-custom {
        font-size: 14pt;
        color: #000 !important;
        border-bottom: 2px solid #000 !important;
    }

    .cargo-nome-principal {
        font-size: 18pt;
        color: #000 !important;
    }

    .cbo-detail, .h5-custom {
        color: #000 !important;
    }

    /* Remove fundos e bordas desnecessários */
    table.data-list th {
        background-color: #fff !important;
        border-color: #888;
    }

    .wysiwyg-content {
        background-color: #fff !important;
        border: none; 
        padding: 10px 0;
    }

    a {
        text-decoration: none;
        color: #000;
    }

    /* Na impressão, força 1 coluna (melhor para A4) */
    .skill-container,
    .section-container { 
        width: 100%;
        overflow: visible;
    }
    .skill-column,
    .section-column { 
        width: 100%;
        float: none;
        margin-right: 0;
    }
}

/*
 * ======================================================
 * AJUSTE 3: Margens ABNT para o PDF
 * ======================================================
 */
@page {
    /* 3cm topo, 2cm direita, 2cm inferior, 3cm esquerda */
    margin: 3cm 2cm 2cm 3cm;
}

